Method.Source:
/// <summary>
/// Extension methode of doExecute()
/// </summary>
protected void doExecute()
{
    WhsrfPassthrough avaPass = controller.parmSessionState().parmPass();

    using (AVACreateContainerIDisposable instance = AVACreateContainerIDisposable::construct())
    {
        if (avaPass.avaParmContainerType())
        {
            instance.containerTypeCode = avaPass.avaParmContainerType();
        }

        next doExecute();
    }
}
